function validate([nums, threshold]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v < 1 || v > 1e9)) return 'Each value is between 1 and 10^9.';
  if (new Set(nums).size !== nums.length) return 'The values in nums must be distinct.';
  if (threshold < 1 || threshold > 200000) return 'threshold is between 1 and 200000.';
  return null;
}

