function countComponents(nums, threshold) {
  const parent = Array.from({ length: threshold + 1 }, (_, value) => value);
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  };
  const union = (a, b) => {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA !== rootB) parent[rootA] = rootB;
  };

  let isolated = 0;
  for (const num of nums) {
    if (num > threshold) {
      isolated++;
      continue;
    }
    for (let multiple = 2 * num; multiple <= threshold; multiple += num) {
      union(num, multiple);
    }
  }

  const roots = new Set();
  for (const num of nums) {
    if (num <= threshold) roots.add(find(num));
  }
  return isolated + roots.size;
}

