function countComponents(nums, threshold) {
  // Build the graph edge by edge from pairwise lcm values, then count components with a depth-first search.
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const n = nums.length;
  const adjacent = Array.from({ length: n }, () => []);
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const lcm = (nums[i] / gcd(nums[i], nums[j])) * nums[j];
      if (lcm <= threshold) { adjacent[i].push(j); adjacent[j].push(i); }
    }
  }
  const seen = new Array(n).fill(false);
  let components = 0;
  for (let i = 0; i < n; i++) {
    if (seen[i]) continue;
    components++;
    const stack = [i];
    seen[i] = true;
    while (stack.length) {
      for (const next of adjacent[stack.pop()]) if (!seen[next]) { seen[next] = true; stack.push(next); }
    }
  }
  return components;
}

