function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 8);
  const threshold = large ? 100000 + Math.floor(rand() * 100001) : 1 + Math.floor(rand() * 40);
  const values = new Set();
  // Mostly values at or below the threshold, some just above it, and now and then a huge one.
  const smallest = large ? Math.floor(rand() * 40) : 0;
  for (let v = 1; v <= smallest; v++) if (rand() < 0.5) values.add(v);
  while (values.size < n) {
    const roll = rand();
    const v = roll < 0.75 ? 1 + Math.floor(rand() * threshold) : roll < 0.95 ? threshold + 1 + Math.floor(rand() * threshold) : 1 + Math.floor(rand() * 1e9);
    values.add(v);
  }
  const nums = [...values];
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, threshold];
}
